// Reimplementation of boltons.iterutils.bucketize (black-box behavioral match).
//
// bucketize(src, key) groups items of `src` by the value returned from
// `key(item)`. Items keep their original relative order, and groups appear
// in the order their key is first encountered (insertion order), matching
// the behavior of a Python dict.

export function bucketize(src, key = (x) => x) {
  const buckets = new Map();
  for (const item of src) {
    const k = key(item);
    if (!buckets.has(k)) {
      buckets.set(k, []);
    }
    buckets.get(k).push(item);
  }
  return buckets;
}

