// Minimal manual reimplementation of the argparse behavior used by test5.py:
//   parser.add_argument('--a', type=str, required=True)
// Supports `--a value` and `--a=value`, plus `-h/--help`. Errors go to
// stderr and exit with code 2, like argparse.

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test5.mjs');

function usage() {
  return `usage: ${PROG} [-h] --a A`;
}

function errorExit(message) {
  process.stderr.write(`${usage()}\n`);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const result = { a: undefined };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(`${usage()}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Comma-separated numbers\n`);
      process.exit(0);
    } else if (arg === '--a') {
      if (i + 1 >= argv.length) {
        errorExit('argument --a: expected one argument');
      }
      result.a = argv[++i];
    } else if (arg.startsWith('--a=')) {
      result.a = arg.slice('--a='.length);
    } else {
      errorExit(`unrecognized arguments: ${arg}`);
    }
  }
  if (result.a === undefined) {
    errorExit('the following arguments are required: --a');
  }
  return result;
}

