// Python-compatible int() parsing for base-10 string literals.
// Python's int() strips surrounding whitespace and accepts an optional sign.
// On failure it raises ValueError; we mirror that with a thrown error whose
// message matches CPython's wording.

export function pyInt(s) {
  const trimmed = s.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    const err = new Error(`invalid literal for int() with base 10: '${s}'`);
    err.name = 'ValueError';
    throw err;
  }
  return parseInt(trimmed, 10);
}

