// Entry point — Node.js port of /workspace/dataset/boltons/test5.py.
// Groups comma-separated numbers by parity using bucketize and prints the
// result with Python-identical formatting.

import { parseArgs } from './lib/argparse.mjs';
import { bucketize } from './lib/bucketize.mjs';
import { pyRepr } from './lib/pyformat.mjs';
import { pyInt } from './lib/pyint.mjs';

const args = parseArgs(process.argv.slice(2));

let numbers;
try {
  numbers = args.a.split(',').map(pyInt);
} catch (err) {
  // Mirror the Python traceback path: unhandled ValueError, exit code 1.
  process.stderr.write(`Traceback (most recent call last):\n`);
  process.stderr.write(`${err.name}: ${err.message}\n`);
  process.exit(1);
}

const result = bucketize(numbers, (x) => x % 2 === 0); // 按奇偶性分组
console.log(pyRepr(result));

